/* Landing v2 type, matching the promo video: Cairo for all text (Arabic + Latin),
 * Poppins 600 for the "Binaya" wordmark only (via var(--font-poppins)).
 *
 * The fonts are self-hosted (public/fonts, @font-face in styles/fonts.css,
 * generated by scripts/fonts/sync-google-fonts.mjs) instead of next/font/google,
 * whose build-time downloads intermittently failed Turbopack builds.
 * Scoped to the marketing page via this class, so the dashboard keeps IBM Plex. */

/** Put on the landing page root: sets Cairo as the font (defined in styles/fonts.css). */
export const landingFontClass = "font-landing";
